inline std::optional<flight::String> get_wgpu_compressed_texture_format(flight::host_sdl::WgpuDevice device, flight::Ref<TextureContainerFormat> format) {
  auto info = get_compressed_format_info(format);
  if (!info.has_value()) {
    return std::nullopt;
  }
  flight::Ref<WgpuCompressedTextureSupport> support = detect_wgpu_compressed_texture_support(device);
  if (format->starts_with(flight::String("bc"))) {
    return (flight::to_boolean(support->bc) ? std::optional<flight::String>{info.value()->format} : std::nullopt);
  }
  if (format->starts_with(flight::String("astc"))) {
    return (flight::to_boolean(support->astc) ? std::optional<flight::String>{info.value()->format} : std::nullopt);
  }
  return (flight::to_boolean(support->etc2) ? std::optional<flight::String>{info.value()->format} : std::nullopt);
}

inline bool has_wgpu_compressed_texture_format(flight::Ref<WgpuCompressedTextureSupport> support, flight::Ref<TextureContainerFormat> format) {
  if (!get_compressed_format_info(format).has_value()) {
    return false;
  }
  if (format->starts_with(flight::String("bc"))) {
    return support->bc;
  }
  if (format->starts_with(flight::String("astc"))) {
    return support->astc;
  }
  return support->etc2;
}

